import {createSlice, createAsyncThunk} from "@reduxjs/toolkit";
import { apiLink } from "../../app/global";
import { PlaceOrder} from "../order/orderSlice";
import {addItemToCart} from "../cart/cartSlice";

export const fetchCurrentUser=createAsyncThunk(
    'user/fetchCurrentUser',
    async (_, {rejectWithValue}) => {
        console.log("fetching current login user")

        const token = localStorage.getItem('token');
        if (!token) {
            return rejectWithValue("No token found");
        }

        try {
            const response=await fetch(`${apiLink}/resource/user`, {
                method: "GET",
                headers: {
                    "Content-Type": "application/json",
                    'Authorization': `Bearer ${token}`,
                    'Accept': 'application/json'
                }
            })

            if(!response.ok) {
                const errorText = await response.text();
                console.error("Error fetching user:", errorText);

                // Only remove token if unauthorized or forbidden
                if (response.status === 401 || response.status === 403) {
                    localStorage.removeItem("token");
                }

                return rejectWithValue(errorText || "Failed to fetch user");
            }

            return await response.json()
            

        } 
        catch(error){
            console.error("Unexpected error:", error);
            
            // Don't remove token on unexpected (e.g. network) error
            // localStorage.removeItem("token");

            return rejectWithValue(error.message || "Failed to fetch current user");
        }
    }
)
export const loginUser=createAsyncThunk(
    'user/loginUser',
    async (credentials, { rejectWithValue} ) =>{
        
        console.log(credentials)
        // {
        // 	"email": "springuser@gg.com",
        // 	"password": "password"
        // }
        

        try {
            const response=await fetch(`${apiLink}/auth/login`, {
                'method': "POST",
                'headers': {
                    'content-type': 'application/json',
                    'accept': 'application/json',

                },
                'body': JSON.stringify(credentials),


            })

            if (!response.ok) {
                // Try to parse error response if possible
                let errorMessage = 'Login failed';
                try {
                    const errorData = await response.json();
                    errorMessage = errorData.message || JSON.stringify(errorData);
                } catch {
                    errorMessage = await response.text();
                }
                console.error('Login error:', errorMessage);
                return rejectWithValue(errorMessage);
            }
            const {token, ...user} = await response.json();
            localStorage.setItem("token", token);  

            return user;

        }
        catch(error){
            return rejectWithValue(error.message || 'Something went wrong');
        }
    }
)
export const logoutUser=createAsyncThunk(
    'user/logoutUser',
    async (_, {rejectWithValue}) =>{
        console.log("in lougout redux")

        try {
            const response=await fetch(`${apiLink}/auth/logout`, {
                'method': "POST",
        
            })
            localStorage.removeItem("token");

            if(!response.ok && response.status!==401) {
                const errorText = await response.text();
                console.log("Logout error :", errorText);
                
                return rejectWithValue(response.status);
            }
            console.log(response)

            return null
            
        } 
        catch(error){
            console.error("Logout request failed:", error);
            localStorage.removeItem("token"); // fallback
            return rejectWithValue(error.message);
        }
    }
)
